records = [
    {'name': '小明', 'scores': [88, 92, 76]},
    {'name': '小红', 'scores': [95, 91, 100]},
    {'name': '小刚', 'scores': [60, 72, 58]},
]

def average(scores):
    if not scores:
        return 0
    return round(sum(scores) / len(scores), 2)


def rank(records):
    return sorted(((r['name'], average(r['scores'])) for r in records),
                  key=lambda item: item[1], reverse=True)


def class_stats(records):
    if not records:
        return {'count': 0, 'avg': 0, 'best': None, 'worst': None}
    scored = [(r['name'], average(r['scores'])) for r in records]
    all_scores = [s for r in records for s in r['scores']]
    return {
        'count': len(records),
        'avg': average(all_scores),
        'best': max(scored, key=lambda i: i[1])[0],
        'worst': min(scored, key=lambda i: i[1])[0],
    }


def level(avg):
    if avg >= 90:
        return '优秀'
    if avg >= 80:
        return '良好'
    if avg >= 60:
        return '及格'
    return '不及格'


print(rank(records))
print(class_stats(records))
for name, avg in rank(records):
    print(name, avg, level(avg))
